CREATE TABLE public.learning_answers (program_id text NOT NULL REFERENCES public.learning_programs(id), activity_id text NOT NULL, content jsonb NOT NULL, PRIMARY KEY(program_id,activity_id));
GRANT SELECT ON public.learning_answers TO authenticated; GRANT ALL ON public.learning_answers TO service_role;
ALTER TABLE public.learning_answers ENABLE ROW LEVEL SECURITY;
CREATE POLICY learning_answer_read ON public.learning_answers FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR (EXISTS(SELECT 1 FROM public.commerce_enrollments e WHERE e.user_id=auth.uid() AND e.product_id=learning_answers.program_id AND e.status='active' AND (e.expires_at IS NULL OR e.expires_at>now())) AND EXISTS(SELECT 1 FROM public.learning_submissions s WHERE s.user_id=auth.uid() AND s.program_id=learning_answers.program_id AND s.activity_id=learning_answers.activity_id AND (jsonb_array_length(s.human_reviews)=0 OR s.reviewed_at IS NOT NULL) AND s.id=(SELECT t.id FROM public.learning_submissions t WHERE t.user_id=auth.uid() AND t.program_id=s.program_id AND t.activity_id=s.activity_id ORDER BY t.submitted_at DESC LIMIT 1))));
INSERT INTO public.learning_answers(program_id,activity_id,content) SELECT p.id,a->>'id',jsonb_build_object('answerHtml',a->'answerHtml','answerIntro',a->'answerIntro','answerVideoUrl',a->'answerVideoUrl','answerFiles',a->'answerFiles','guideDocs',a->'guideDocs','referenceDoc',a->'referenceDoc') FROM public.learning_programs p CROSS JOIN LATERAL jsonb_array_elements(p.content->'activities') a;
UPDATE public.learning_programs p SET content=jsonb_set(content,'{activities}',(SELECT jsonb_agg(a-'answerHtml'-'answerIntro'-'answerVideoUrl'-'answerFiles'-'guideDocs'-'referenceDoc' || jsonb_build_object('answerIntro','','answerVideoUrl','','answerFiles','[]'::jsonb,'guideDocs','[]'::jsonb,'referenceDoc',jsonb_build_object('name','','content','','description',''))) FROM jsonb_array_elements(p.content->'activities') a));